#include "neurogenic/ui/gui.hpp"
#include <algorithm>
#include <cmath>
#include <limits>

namespace neurogenic {
GuiLayout GuiModel::layout(int width,int height) const{GuiLayout result;result.scale=std::max(0.5F,std::min(width/1024.0F,height/600.0F));result.offset_x=(width-1024*result.scale)/2;result.offset_y=(height-600*result.scale)/2;auto r=[&](float x,float y,float w,float h){return UiRect{result.offset_x+x*result.scale,result.offset_y+y*result.scale,w*result.scale,h*result.scale};};result.top=r(0,0,1024,64);result.nav=r(0,64,1024,54);result.content=r(16,130,744,454);result.parameters=r(776,130,232,454);for(int i=0;i<4;++i)result.tabs.push_back(r(16+i*184,72,176,38));for(int i=0;i<16;++i)result.grid.push_back(r(32+(i%8)*88,250+(i/8)*92,78,78));for(int i=0;i<8;++i)result.rows.push_back(r(28,150+i*46,716,38));return result;}
const GuiFrame& GuiModel::frame(int width,int height){const auto state=application_.snapshot();if(frame_.state_revision!=state.revision||frame_.layout.content.w==0){frame_.state_revision=state.revision;frame_.layout=layout(width,height);render(state,frame_.layout);}return frame_;}
void GuiModel::submit(ApplicationCommand command){auto result=application_.execute(command);if(!result.accepted)error_=result.error;else error_.clear();frame_.state_revision=std::numeric_limits<std::uint64_t>::max();}
void GuiModel::render(const ApplicationState& state,const GuiLayout& l){frame_.commands.clear();auto rect=[&](UiRect r,UiColor c){frame_.commands.push_back({DrawCommand::Type::rectangle,r,c,{}});};auto text=[&](UiRect r,UiColor c,std::string value){frame_.commands.push_back({DrawCommand::Type::text,r,c,std::move(value)});};rect({0,0,l.offset_x*2+1024*l.scale,l.offset_y*2+600*l.scale},UiColor::background);rect(l.top,UiColor::panel);text({l.top.x+16*l.scale,l.top.y+12*l.scale,990*l.scale,30*l.scale},UiColor::text,"NEUROGENIC   "+std::to_string(static_cast<int>(std::round(state.tempo_bpm)))+" BPM   "+std::to_string(state.time_signature_numerator)+"/"+std::to_string(state.time_signature_denominator)+"   "+(state.playing?"PLAY":"STOP")+"   TRACK "+std::to_string(state.selected_track)+"   "+pad_mode_name(state.pad_mode));const char* names[]{"SEQUENCER","SAMPLES","PARAMETERS","X/Y"};for(std::size_t i=0;i<l.tabs.size();++i){rect(l.tabs[i],i==static_cast<std::size_t>(view_)?UiColor::selected:UiColor::panel);text(l.tabs[i],UiColor::text,names[i]);}rect(l.content,UiColor::panel);rect(l.parameters,UiColor::panel);
  if(view_==GuiView::sequencer){text({l.content.x+12,l.content.y+8,l.content.w-24,28*l.scale},UiColor::accent,"TIMELINE / STEP PAGE "+std::to_string(state.step_page+1));for(std::size_t i=0;i<std::min(l.rows.size(),state.tracks.size());++i){const auto& track=state.tracks[i];rect(l.rows[i],track.id==state.selected_track?UiColor::selected:UiColor::background);text(l.rows[i],track.muted?UiColor::muted:UiColor::text,std::to_string(track.id)+"  "+track.name+"  "+std::to_string(track.pattern_length)+" ticks"+(track.muted?"  MUTED":""));}for(std::size_t i=0;i<l.grid.size();++i){rect(l.grid[i],state.selected_step==static_cast<std::int64_t>(state.step_page*16+i)?UiColor::selected:UiColor::background);text(l.grid[i],UiColor::text,std::to_string(state.step_page*16+i+1));}text({l.content.x+12,l.content.y+l.content.h-24*l.scale,l.content.w,18*l.scale},UiColor::unavailable,"STEP EDIT UNAVAILABLE - selection only");}
  else if(view_==GuiView::samples){text({l.content.x+12,l.content.y+8,l.content.w,28*l.scale},UiColor::accent,"SAMPLE SLOTS");for(std::size_t i=0;i<l.rows.size();++i){const auto slot=static_cast<std::uint32_t>(i);const auto found=std::find_if(state.sample_slots.begin(),state.sample_slots.end(),[&](const auto& s){return s.id.value==slot;});std::string label="SLOT "+std::to_string(slot)+"  EMPTY";UiColor color=slot==state.selected_sample_slot.value?UiColor::selected:UiColor::text;if(found!=state.sample_slots.end())label="SLOT "+std::to_string(slot)+"  "+sample_slot_state_name(found->state)+"  "+found->source_path.filename().string()+(found->error.empty()?"":"  "+found->error);rect(l.rows[i],slot==state.selected_sample_slot.value?UiColor::selected:UiColor::background);text(l.rows[i],found!=state.sample_slots.end()&&!found->error.empty()?UiColor::error:color,label);}text({l.content.x+12,l.content.y+l.content.h-24*l.scale,l.content.w,18*l.scale},UiColor::muted,"Set path, then Enter=load/replace; Delete action via Back");}
  else if(view_==GuiView::parameters){text({l.content.x+12,l.content.y+8,l.content.w,28*l.scale},UiColor::accent,"APPLICATION PARAMETERS");for(std::size_t i=0;i<std::min(l.rows.size(),state.parameters.size());++i){const auto& p=state.parameters[i];rect(l.rows[i],i==parameter_index_?UiColor::selected:UiColor::background);std::string value=std::holds_alternative<double>(p.current_value)?std::to_string(std::get<double>(p.current_value)):"value";text(l.rows[i],UiColor::text,p.name+"  "+value+" "+p.unit);}}
  else {text({l.content.x+12,l.content.y+8,l.content.w,28*l.scale},UiColor::accent,"X/Y PERFORMANCE");UiRect pad{l.content.x+60*l.scale,l.content.y+56*l.scale,360*l.scale,360*l.scale};rect(pad,UiColor::background);double x=.5,y=.5;for(const auto& p:state.parameters){if(p.id=="performance.xy.x")x=std::get<double>(p.current_value);if(p.id=="performance.xy.y")y=std::get<double>(p.current_value);}rect({pad.x+static_cast<float>(x)*pad.w-10*l.scale,pad.y+static_cast<float>(y)*pad.h-10*l.scale,20*l.scale,20*l.scale},UiColor::accent);text({pad.x,pad.y+pad.h+8*l.scale,pad.w,20*l.scale},UiColor::text,"X "+std::to_string(x)+"   Y "+std::to_string(y));}
  text({l.parameters.x+12,l.parameters.y+12,l.parameters.w-24,28*l.scale},UiColor::accent,"CONTEXT");text({l.parameters.x+12,l.parameters.y+54*l.scale,l.parameters.w-24,90*l.scale},UiColor::text,"Focus: "+state.focused_element+"\nSlot: "+std::to_string(state.selected_sample_slot.value)+"\nRevision: "+std::to_string(state.revision));if(!error_.empty())text({l.parameters.x+12,l.parameters.y+l.parameters.h-70*l.scale,l.parameters.w-24,60*l.scale},UiColor::error,error_);}
bool GuiModel::input(const GuiInput& input,int width,int height){const auto l=layout(width,height);auto state=application_.snapshot();auto command=[&](std::string id){submit({std::move(id)});};if(input.type==GuiInput::Type::key_down){if(input.key==GuiKey::tab||input.key==GuiKey::right)command("navigation.focus-next.v1");else if(input.key==GuiKey::left)command("navigation.focus-previous.v1");else if(input.key==GuiKey::enter){if(view_==GuiView::samples&&!sample_path_.empty())submit({"sample.replace.v1",{{"slot_id",static_cast<std::int64_t>(state.selected_sample_slot.value)},{"path",sample_path_.string()}}});else command("navigation.confirm.v1");}else if(input.key==GuiKey::escape){if(view_==GuiView::samples)submit({"sample.unload.v1",{{"slot_id",static_cast<std::int64_t>(state.selected_sample_slot.value)}}});else command("navigation.cancel.v1");}else if(input.key==GuiKey::space)command(state.playing?"transport.stop.v1":"transport.play.v1");else if(input.key==GuiKey::shift){shift_=true;submit({"modifier.shift.v1",{{"active",true}}});}else if(input.key==GuiKey::number&&input.number>=1&&input.number<=16)submit({"step.select.v1",{{"step",static_cast<std::int64_t>(state.step_page*16+input.number-1)}}});else if((input.key==GuiKey::up||input.key==GuiKey::down)&&view_==GuiView::parameters&&!state.parameters.empty()){const double steps=input.key==GuiKey::up?1:-1;submit({"parameter.adjust.v1",{{"parameter_id",state.parameters[parameter_index_%state.parameters.size()].id},{"steps",steps}}});}else if((input.key==GuiKey::up||input.key==GuiKey::down)&&view_==GuiView::xy){double dx=0,dy=input.key==GuiKey::up?-.02:.02;submit({"modulation.xy.v1",{{"position",NormalizedXY{.5+dx,.5+dy}}}});}return true;}if(input.type==GuiInput::Type::key_up&&input.key==GuiKey::shift){shift_=false;submit({"modifier.shift.v1",{{"active",false}}});return true;}
  const bool down=input.type==GuiInput::Type::pointer_down||input.type==GuiInput::Type::touch_down;const bool move=input.type==GuiInput::Type::pointer_move||input.type==GuiInput::Type::touch_move;const bool up=input.type==GuiInput::Type::pointer_up||input.type==GuiInput::Type::touch_up;if(down){pointer_down_=true;for(std::size_t i=0;i<l.tabs.size();++i)if(l.tabs[i].contains(input.x,input.y)){view_=static_cast<GuiView>(i);frame_.state_revision=~0ULL;return true;}if(view_==GuiView::sequencer)for(std::size_t i=0;i<l.grid.size();++i)if(l.grid[i].contains(input.x,input.y)){submit({"step.select.v1",{{"step",static_cast<std::int64_t>(state.step_page*16+i)}}});return true;}if(view_==GuiView::samples)for(std::size_t i=0;i<l.rows.size();++i)if(l.rows[i].contains(input.x,input.y)){submit({"sample.slot-select.v1",{{"slot_id",static_cast<std::int64_t>(i)}}});return true;}if(view_==GuiView::parameters)for(std::size_t i=0;i<std::min(l.rows.size(),state.parameters.size());++i)if(l.rows[i].contains(input.x,input.y)){parameter_index_=i;frame_.state_revision=~0ULL;return true;}}
  if((move&&pointer_down_)||down){if(view_==GuiView::xy){UiRect pad{l.content.x+60*l.scale,l.content.y+56*l.scale,360*l.scale,360*l.scale};if(pad.contains(input.x,input.y)&&(input.timestamp_ms>=last_xy_ms_+8||down)){last_xy_ms_=input.timestamp_ms;submit({"modulation.xy.v1",{{"position",NormalizedXY{std::clamp((input.x-pad.x)/pad.w,0.0F,1.0F),std::clamp((input.y-pad.y)/pad.h,0.0F,1.0F)}}}});return true;}}}if(up){pointer_down_=false;return true;}return false;}
std::vector<std::filesystem::directory_entry> GuiModel::browse(const std::filesystem::path& path,std::string& error) const{try{std::vector<std::filesystem::directory_entry> result;for(const auto& entry:std::filesystem::directory_iterator(path))if(entry.is_directory()||entry.path().extension()==".wav")result.push_back(entry);std::sort(result.begin(),result.end(),[](const auto& a,const auto& b){return a.path()<b.path();});error.clear();return result;}catch(const std::exception& exception){error=exception.what();return{};}}
}
